package es.iesquevedo.service.impl;

import es.iesquevedo.exception.NotFoundException;
import es.iesquevedo.repository.MainRepository;
import es.iesquevedo.service.MainService;

public class MainServiceImpl implements MainService {
    private final MainRepository repository;

    public MainServiceImpl(MainRepository repository) {
        this.repository = repository;
    }

    @Override
    public String greet() {
        String name = repository.findDefaultName();
        if (name == null || name.isBlank()) {
            throw new NotFoundException("Default player name not found");
        }
        return "Hello, " + name + "!";
    }
}

package es.iesquevedo.exception;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;

class MainErrorHandlerTest {

    @Test
    void toApiError_shouldMapNotFoundTo404() {
        MainErrorHandler handler = new MainErrorHandler();

        ApiError result = handler.toApiError(new NotFoundException("Resource not found"));

        assertEquals(404, result.getCode());
        assertEquals("Resource not found", result.getMessage());
    }

    @Test
    void toApiError_shouldMapGenericRuntimeExceptionTo500() {
        MainErrorHandler handler = new MainErrorHandler();

        ApiError result = handler.toApiError(new RuntimeException("boom"));

        assertEquals(500, result.getCode());
        assertEquals("Internal error", result.getMessage());
    }
}

package es.iesquevedo.model;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.util.Set;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

class BoardTest {

    private Board board;

    @BeforeEach
    void setUp() {
        board = new Board();
    }

    @Test
    void testInitialBoardIsEmpty() {
        for (int r = 0; r < 9; r++) {
            for (int c = 0; c < 9; c++) {
                assertEquals(0, board.getCell(r, c), "Tablero debe estar vacío inicialmente");
            }
        }
    }

    @Test
    void testPlaceAndRemoveStone() {
        board.placeStone(0, 0, 1); // Colocar piedra negra
        assertEquals(1, board.getCell(0, 0));

        board.removeStone(0, 0);
        assertEquals(0, board.getCell(0, 0));
    }

    @Test
    void testIsValid() {
        assertTrue(board.isValid(0, 0));
        assertTrue(board.isValid(8, 8));
        assertFalse(board.isValid(-1, 0));
        assertFalse(board.isValid(9, 0));
        assertFalse(board.isValid(0, -1));
        assertFalse(board.isValid(0, 9));
    }

    @Test
    void testIsEmpty() {
        assertTrue(board.isEmpty(0, 0));

        board.placeStone(0, 0, 1);
        assertFalse(board.isEmpty(0, 0));
    }

    @Test
    void testGetNeighbors() {
        // Centro: debe tener 4 vecinos
        var neighbors = board.getNeighbors(4, 4);
        assertEquals(4, neighbors.size());

        // Esquina: debe tener 2 vecinos
        neighbors = board.getNeighbors(0, 0);
        assertEquals(2, neighbors.size());
    }

    @Test
    void testCountLibertiesForSingleStone() {
        board.placeStone(4, 4, 1);
        int liberties = board.countLibertiesForGroup(4, 4);
        assertEquals(4, liberties, "Piedra aislada debe tener 4 libertades");
    }

    @Test
    void testCountLibertiesForConnectedGroup() {
        // Grupo de 2 piedras conectadas
        board.placeStone(4, 4, 1);
        board.placeStone(4, 5, 1);

        int liberties = board.countLibertiesForGroup(4, 4);
        assertEquals(6, liberties, "Grupo de 2 debe tener 6 libertades (sin contar duplicadas)");
    }

    @Test
    void testCountLibertiesWithBlockedGroup() {
        // Piedra negra rodeada parcialmente
        board.placeStone(4, 4, 1);
        board.placeStone(3, 4, 2); // Blanco arriba
        board.placeStone(5, 4, 2); // Blanco abajo

        int liberties = board.countLibertiesForGroup(4, 4);
        assertEquals(2, liberties, "Piedra con 2 lados bloqueados debe tener 2 libertades");
    }

    @Test
    void testGetGroup() {
        // Crear grupo de 3 piedras conectadas (L-shape)
        board.placeStone(4, 4, 1);
        board.placeStone(4, 5, 1);
        board.placeStone(5, 5, 1);

        Set<String> group = board.getGroup(4, 4);
        assertEquals(3, group.size(), "Grupo debe tener 3 piedras");
        assertTrue(group.contains("4,4"));
        assertTrue(group.contains("4,5"));
        assertTrue(group.contains("5,5"));
    }

    @Test
    void testCaptureGroupWithoutLiberties() {
        // Rodear completamente un grupo blanco
        // . . W . .
        // . N N N .
        // . W W W .
        board.placeStone(0, 2, 2); // Blanco arriba
        board.placeStone(1, 1, 1); // Negro izq
        board.placeStone(1, 2, 1); // Negro centro
        board.placeStone(1, 3, 1); // Negro der
        board.placeStone(2, 1, 2); // Blanco izq
        board.placeStone(2, 2, 2); // Blanco centro
        board.placeStone(2, 3, 2); // Blanco der

        // Cerrar: Negro coloca en (0,3) capturando Blanco
        board.placeStone(0, 3, 1);
        board.placeStone(1, 0, 1); // Pared izquierda
        board.placeStone(0, 1, 1); // Pared arriba-izq

        int captured = board.captureGroupsWithoutLiberties();
        assertTrue(captured > 0, "Debe haber capturado piedras");

        // Verificar que las piedras blancas fueron removidas
        assertEquals(0, board.getCell(0, 2), "Piedra blanca (0,2) debe estar capturada");
    }

    @Test
    void testBoardClone() {
        board.placeStone(0, 0, 1);
        board.placeStone(1, 1, 2);

        Board cloned = board.clone();
        assertEquals(board.getCell(0, 0), cloned.getCell(0, 0));
        assertEquals(board.getCell(1, 1), cloned.getCell(1, 1));

        // Modificar el clon no debe afectar el original
        cloned.placeStone(2, 2, 1);
        assertEquals(0, board.getCell(2, 2), "Original no debe ser afectado");
        assertEquals(1, cloned.getCell(2, 2), "Clon debe tener el cambio");
    }

    @Test
    void testBoardEquals() {
        Board board2 = new Board();
        assertTrue(board.equals(board2), "Dos tableros vacíos deben ser iguales");

        board.placeStone(0, 0, 1);
        assertFalse(board.equals(board2), "Tableros con diferentes estados deben ser distintos");

        board2.placeStone(0, 0, 1);
        assertTrue(board.equals(board2), "Tableros con mismo estado deben ser iguales");
    }
}

package es.iesquevedo.service;

import es.iesquevedo.exception.InvalidMoveException;
import es.iesquevedo.exception.PlayerNotInTurnException;
import es.iesquevedo.model.Game;
import es.iesquevedo.model.GameState;
import es.iesquevedo.model.Player;
import es.iesquevedo.service.impl.GameServiceImpl;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Tests unitarios de GameService.
 */
public class GameServiceTest {

    private GameService gameService;
    private Player player1;
    private Player player2;

    @BeforeEach
    void setUp() {
        gameService = new GameServiceImpl();
        player1 = new Player("p1", "Alice");
        player2 = new Player("p2", "Bob");
    }

    @Test
    void testCreateGame() {
        Game game = gameService.createGame("Inazuma Match", player1);

        assertNotNull(game);
        assertEquals("Inazuma Match", game.getName());
        assertEquals(GameState.WAITING, game.getState());
        assertEquals(1, game.getPlayers().size());
        assertEquals(player1, game.getPlayers().get(0));
    }

    @Test
    void testJoinGame() {
        Game game = gameService.createGame("Inazuma Match", player1);
        game = gameService.joinGame(game.getId(), player2);

        assertEquals(2, game.getPlayers().size());
        assertEquals(player2, game.getPlayers().get(1));
        assertEquals(GameState.WAITING, game.getState());
    }

    @Test
    void testJoinGameCannotAddThirdPlayer() {
        Game game = gameService.createGame("Inazuma Match", player1);
        gameService.joinGame(game.getId(), player2);

        Player player3 = new Player("p3", "Charlie");
        assertThrows(IllegalStateException.class, () -> gameService.joinGame(game.getId(), player3));
    }

    @Test
    void testStartGame() {
        Game game = gameService.createGame("Inazuma Match", player1);
        gameService.joinGame(game.getId(), player2);

        game = gameService.startGame(game.getId());

        assertEquals(GameState.IN_PROGRESS, game.getState());
        assertEquals(0, game.getCurrentPlayerIndex());
    }

    @Test
    void testStartGameRequiresTwoPlayers() {
        Game game = gameService.createGame("Inazuma Match", player1);

        assertThrows(IllegalStateException.class, () -> gameService.startGame(game.getId()));
    }

    @Test
    void testNextTurn() {
        Game game = gameService.createGame("Inazuma Match", player1);
        gameService.joinGame(game.getId(), player2);
        game = gameService.startGame(game.getId());

        assertEquals(0, game.getCurrentPlayerIndex());
        assertEquals(0, game.getTurnCount());

        game = gameService.nextTurn(game.getId());

        assertEquals(1, game.getCurrentPlayerIndex());
        assertEquals(1, game.getTurnCount());

        game = gameService.nextTurn(game.getId());

        assertEquals(0, game.getCurrentPlayerIndex());
        assertEquals(2, game.getTurnCount());
    }

    @Test
    void testExecuteMoveValidatesPlayerTurn() {
        Game game = gameService.createGame("Inazuma Match", player1);
        gameService.joinGame(game.getId(), player2);
        final Game startedGame = gameService.startGame(game.getId());

        // Intenta mover con player2 pero es turno de player1
        assertThrows(PlayerNotInTurnException.class, 
            () -> gameService.executeMove(startedGame.getId(), player2.getId(), null));
    }

    @Test
    void testExecuteMoveValidatesPlayerAlive() {
        Game game = gameService.createGame("Inazuma Match", player1);
        gameService.joinGame(game.getId(), player2);
        final Game startedGame = gameService.startGame(game.getId());

        // Marca player1 como muerto
        startedGame.getCurrentPlayer().setAlive(false);

        assertThrows(InvalidMoveException.class, 
            () -> gameService.executeMove(startedGame.getId(), player1.getId(), null));
    }

    @Test
    void testFinishGame() {
        Game game = gameService.createGame("Inazuma Match", player1);
        gameService.joinGame(game.getId(), player2);
        gameService.startGame(game.getId());

        game = gameService.finishGame(game.getId(), player1.getId());

        assertEquals(GameState.FINISHED, game.getState());
        assertEquals(player1.getId(), game.getWinnerPlayerId());
        assertNotNull(game.getFinishedAt());
    }

    @Test
    void testAbandonGame() {
        Game game = gameService.createGame("Inazuma Match", player1);
        gameService.joinGame(game.getId(), player2);
        gameService.startGame(game.getId());

        game = gameService.abandonGame(game.getId());

        assertEquals(GameState.ABANDONED, game.getState());
        assertNotNull(game.getFinishedAt());
    }

    @Test
    void testGetGameReturnsNull() {
        assertNull(gameService.getGame("nonexistent"));
    }
}

package es.iesquevedo.service;

import es.iesquevedo.exception.InvalidMoveException;
import es.iesquevedo.exception.PlayerNotInTurnException;
import es.iesquevedo.model.Game;
import es.iesquevedo.model.GameState;
import es.iesquevedo.model.Move;
import es.iesquevedo.model.Player;
import es.iesquevedo.service.impl.GameServiceImpl;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

