        assertEquals(0, game.getCurrentPlayerIndex());
        assertEquals(0, game.getTurnCount());

        game = gameService.nextTurn(game.getId());

        assertEquals(1, game.getCurrentPlayerIndex());
        assertEquals(1, game.getTurnCount());

        game = gameService.nextTurn(game.getId());

        assertEquals(0, game.getCurrentPlayerIndex());
